<template>
    <div>
        <Head title="Regular Forms" />

        <div class="row">
            <div class="md:col-6">
                <Card title="Stacked Form" icon="mail_outline" card-header-class="card-header-rose">
                    <form id="stacked-demo" @submit.prevent="submittedForm = 'stacked'">
                        <TextInputGroup name="stacked-email" type="email" label="Email Address" autocomplete="email" />
                        <TextInputGroup name="stacked-password" type="password" label="Password" autocomplete="off" />
                        <Checkbox v-model:checked="newsletter">Subscribe to newsletter</Checkbox>
                        <p v-if="submittedForm === 'stacked'" class="fg-success mb-0" role="status">Demo form submitted.</p>
                    </form>
                    <template #footer>
                        <button type="submit" form="stacked-demo" class="btn btn-rose">Submit</button>
                    </template>
                </Card>
            </div>
            <div class="md:col-6">
                <Card title="Horizontal Form" icon="contacts" card-header-class="card-header-rose">
                    <form id="horizontal-demo" @submit.prevent="submittedForm = 'horizontal'">
                        <div class="row align-items-center mb-2">
                            <label for="horizontal-email" class="md:col-3 col-form-label">Email</label>
                            <div class="md:col-9">
                                <TextInputGroup name="horizontal-email" type="email" autocomplete="email" />
                            </div>
                        </div>
                        <div class="row align-items-center mb-2">
                            <label for="horizontal-password" class="md:col-3 col-form-label">Password</label>
                            <div class="md:col-9">
                                <TextInputGroup name="horizontal-password" type="password" autocomplete="off" />
                            </div>
                        </div>
                        <div class="row">
                            <div class="md:col-9 ms-auto">
                                <Checkbox v-model:checked="remember">Remember me</Checkbox>
                                <p v-if="submittedForm === 'horizontal'" class="fg-success mb-0" role="status">Demo form submitted.</p>
                            </div>
                        </div>
                    </form>
                    <template #footer>
                        <div class="row w-100">
                            <div class="md:col-9 ms-auto">
                                <button type="submit" form="horizontal-demo" class="btn btn-rose">Sign in</button>
                            </div>
                        </div>
                    </template>
                </Card>
            </div>
        </div>

        <Card card-header-class="card-header-rose card-header-text">
            <template #header>
                <div class="card-text"><h4 class="card-title">Form Elements</h4></div>
            </template>

            <div class="row mb-3">
                <label for="element-help" class="sm:col-2 col-form-label">With help</label>
                <div class="sm:col-10">
                    <input id="element-help" type="text" class="form-control" aria-describedby="element-help-text" />
                    <div id="element-help-text" class="form-text">A block of help text that breaks onto a new line.</div>
                </div>
            </div>
            <div v-for="field in textFields" :key="field.id" class="row align-items-center mb-3">
                <label :for="field.id" class="sm:col-2 col-form-label">{{ field.label }}</label>
                <div class="sm:col-10">
                    <TextInputGroup
                        :name="field.id"
                        :type="field.type"
                        :placeholder="field.placeholder"
                        :model-value="field.value"
                        :disabled="field.disabled"
                    />
                </div>
            </div>
            <div class="row align-items-center mb-3">
                <div class="sm:col-2 col-form-label">Static control</div>
                <div class="sm:col-10"><p class="mb-0">hello@creative-tim.com</p></div>
            </div>
            <div class="row mb-3" role="group" aria-labelledby="form-elements-choices">
                <div id="form-elements-choices" class="sm:col-2 col-form-label">Checkboxes and radios</div>
                <div class="sm:col-10">
                    <Checkbox v-for="choice in checkboxLabels" :key="choice" v-model:checked="checkedChoices" :value="choice">
                        {{ choice }}
                    </Checkbox>
                    <div v-for="choice in radioLabels" :key="choice" class="form-check">
                        <label class="form-check-label">
                            <input v-model="selectedRadio" class="form-check-input" type="radio" name="element-radio" :value="choice" />
                            {{ choice }}
                            <span class="circle" aria-hidden="true"><span class="material-check-mark"></span></span>
                        </label>
                    </div>
                </div>
            </div>
            <div class="row" role="group" aria-labelledby="inline-checkboxes">
                <div id="inline-checkboxes" class="sm:col-2 col-form-label">Inline checkboxes</div>
                <div class="sm:col-10 d-flex flex-wrap gap-3">
                    <Checkbox v-for="choice in ['a', 'b', 'c']" :key="choice" v-model:checked="inlineChoices" :value="choice">
                        {{ choice }}
                    </Checkbox>
                </div>
            </div>
        </Card>

        <Card card-header-class="card-header-rose card-header-text">
            <template #header>
                <div class="card-text"><h4 class="card-title">Input Variants</h4></div>
            </template>

            <div class="row mb-3" role="group" aria-labelledby="input-variants-choices">
                <div id="input-variants-choices" class="sm:col-2 col-form-label">Custom Checkboxes &amp; radios</div>
                <div class="sm:col-4 sm:offset-1">
                    <Checkbox v-for="checkbox in checkboxVariants" :key="checkbox.label" v-model:checked="checkbox.checked" :disabled="checkbox.disabled">
                        {{ checkbox.label }}
                    </Checkbox>
                </div>
                <div class="sm:col-4">
                    <div v-for="radio in radioVariants" :key="radio.label" class="form-check">
                        <label class="form-check-label">
                            <input
                                class="form-check-input"
                                type="radio"
                                :name="radio.disabled ? 'disabled-variant-radio' : 'variant-radio'"
                                :checked="radio.disabled ? radio.value === 'on' : selectedVariant === radio.value"
                                :disabled="radio.disabled"
                                @change="selectedVariant = radio.value"
                            />
                            {{ radio.label }}
                            <span class="circle" aria-hidden="true"><span class="material-check-mark"></span></span>
                        </label>
                    </div>
                </div>
            </div>
            <div v-for="field in validationFields" :key="field.id" class="row align-items-center mb-3">
                <label :for="field.id" class="sm:col-2 col-form-label">{{ field.label }}</label>
                <div class="sm:col-10">
                    <div class="position-relative" :class="field.invalid ? 'has-danger' : 'has-success'">
                        <input
                            :id="field.id"
                            type="text"
                            class="form-control pe-5"
                            :class="field.invalid ? 'is-invalid' : 'is-valid'"
                            :aria-invalid="field.invalid || undefined"
                        />
                        <span class="form-control-feedback" aria-hidden="true">
                            <i class="material-icons">{{ field.invalid ? 'clear' : 'done' }}</i>
                        </span>
                    </div>
                </div>
            </div>
            <div class="row align-items-center" role="group" aria-labelledby="form-column-sizing">
                <div id="form-column-sizing" class="sm:col-2 col-form-label">Column sizing</div>
                <div class="sm:col-10">
                    <div class="row">
                        <div v-for="size in [3, 4, 5]" :key="size" :class="`md:col-${size}`">
                            <input type="text" class="form-control" :aria-label="`${size}-column input`" :placeholder="`md:col-${size}`" />
                        </div>
                    </div>
                </div>
            </div>
        </Card>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';
import Checkbox from '@scaffold/components/Checkbox.vue';
import TextInputGroup from '@scaffold/components/TextInputGroup.vue';

export default {
    name: 'RegularFormsDemo',
    components: { Card, Checkbox, Head, TextInputGroup },
    layout: { pageTitle: 'Regular Forms' },
    data() {
        return {
            submittedForm: null,
            newsletter: false,
            remember: false,
            checkedChoices: [],
            inlineChoices: [],
            selectedRadio: 'First Radio',
            selectedVariant: 'on',
            checkboxLabels: ['First Checkbox', 'Second Checkbox'],
            radioLabels: ['First Radio', 'Second Radio'],
            textFields: [
                { id: 'element-password', label: 'Password', type: 'password' },
                { id: 'element-placeholder', label: 'Placeholder', placeholder: 'placeholder' },
                { id: 'element-disabled', label: 'Disabled', value: 'Disabled input here…', disabled: true },
            ],
            checkboxVariants: [
                { label: 'Checked', checked: true },
                { label: 'Unchecked', checked: false },
                { label: 'Disabled Checked', checked: true, disabled: true },
                { label: 'Disabled Unchecked', checked: false, disabled: true },
            ],
            radioVariants: [
                { label: 'Radio is on', value: 'on' },
                { label: 'Radio is off', value: 'off' },
                { label: 'Disabled Radio is on', value: 'on', disabled: true },
                { label: 'Disabled Radio is off', value: 'off', disabled: true },
            ],
            validationFields: [
                { id: 'success-input', label: 'Input with success' },
                { id: 'error-input', label: 'Input with error', invalid: true },
            ],
        };
    },
};
</script>
